 const combined=category==='hair-nails',group=C.serviceCategories?.find(x=>x.id===category),title=combined?entryCopy('Tırnak ve Saç','Dırnaq və Saç','Ногти и волосы'):name(group)||t('services'),list=C.services.filter(x=>!category||(combined?['hair','nails'].includes(x.categoryId):x.categoryId===category||x.category===category||x.id===category)).sort((a,b)=>combined?(a.categoryId==='nails'?0:1)-(b.categoryId==='nails'?0:1):0),photo=category&&mediaSrc('category',category);
