 return `<section class="source-category-screen ${photo?'has-photo':'photo-free'}" data-source="service_category_variants"><header class="source-discover-subheader"><a class="icon-button" href="#discover" aria-label="${e(t('back'))}">${sourceIcon('lucide:chevron-left','back')}</a><div><h1 tabindex="-1">${e(title)}</h1><p>${e(entryCopy('Hizmet Seçimi','Xidmət Seçimi','Выбор услуги'))}</p></div></header>${photo?`<div class="source-category-hero" data-media-slot="image">${mediaImage('category',category,{alt:title})}</div>`:''}<div class="source-category-cards">${session.ui?.rebookNotice?.kind==='rebookSelectService'?note('rebookSelectService'):''}${list.flatMap(service=>service.variants.map(v=>`<article class="source-category-card"><div class="source-category-card-heading"><div><h2>${e(name(service))}${entryVariantLabel(v)?' · '+e(entryVariantLabel(v)):''}</h2><p>${entryGlyph('clock')}<span>${v.duration} ${e(language==='tr'?'dk':t('minutes'))}</span></p></div><strong>${money(v.priceMinor)}</strong></div><a class="source-category-select" href="#service/${e(service.id)}/${e(v.id)}">${e(entryCopy('Seç','Seç','Выбрать'))}</a></article>`)).join('')||(!information.length?sourceEmpty('search'):'')}${serviceInformationRows(information)}</div></section>`;
