function visitChoiceFormCurrent(data){const actual=A.getSession(),owner=String(data.get('visitChoiceOwner')||''),snapshot=String(data.get('visitChoiceDraft')||'');if(!actual.customerId||owner!==actual.customerId||owner!==cid()){session=actual;message('code.session_changed');return false;}if(snapshot!==JSON.stringify(actual.draft||{items:[]})){session=actual;flash=entryCopy('Sepet değişti. Güncel seçimlerinizi kontrol edin.','Səbət dəyişib. Cari seçimlərinizi yoxlayın.','Корзина изменилась. Проверьте текущий выбор.');flashKind='error';return false;}session=actual;return true;}
