 const pendingSchedule=needsChoice?`<section class="visit-choice-basket-schedule" data-source="schedule-conflict-section_004"><div class="visit-choice-basket-range">${sourceIcon('solar:calendar-bold-duotone','visits')}<div><h2>${e(entryCopy('Seçilen Zaman Aralığı','Seçilmiş Vaxt Aralığı','Выбранное время'))}</h2>${visitChoiceLines(d).map(x=>`<p>${reservationDates(d).length>1?e(date(x.date))+' · ':''}${e(x.time)} - ${e(endTime(x))}</p>`).join('')}</div></div><div class="visit-choice-basket-hint">${sourceIcon('solar:info-circle-bold','info')}<p>${e(actual.code==='VISIT_CHOICE_REQUIRED'?entryCopy('Bu tarihte mevcut ziyaretiniz var. Devam etmek için ziyaret seçiminizi yapın.','Bu tarixdə mövcud ziyarətiniz var. Davam etmək üçün ziyarətinizi seçin.','На эту дату уже есть визит. Чтобы продолжить, выберите визит.'):flowText('visitChanged'))}</p></div></section>`:'';
