  <div class="group-hero ${mediaSrc('class',id)?'':'safe-media-photofree'}" data-source="hero_002">${mediaImage('class',id)}<a class="icon-button" href="#discover/classes" aria-label="${e(t('back'))}">${icon('back')}</a><div class="classfix-group-title">${allFull?badge('full'):''}<h1 tabindex="-1">${e(name(p))}</h1></div></div>
