 if(info.pending.length&&(detail||!can))body+=`<section class="memberfix-history"><h2>${e(t('requests'))}</h2>${info.pending.map(r=>listRow(t(r.type.replace('membership-','')),date(r.createdAt),'request-detail/'+r.id,r.status)).join('')}</section>`;
