function supportRouteTarget(){const parts=location.hash.slice(1).split('/').slice(1).map(x=>{try{return decodeURIComponent(x);}catch{return x;}});return parts.length>=2?parts[0]+':'+parts.slice(1).join('/'):'';}
function supportDraft(routeTarget=''){const list=Array.isArray(session.ui?.supportDrafts)?session.ui.supportDrafts:[],ownerId=cid()||null;let saved=list.find(x=>x.ownerId===ownerId&&x.routeTarget===routeTarget);if(!saved&&ownerId){const guest=list.find(x=>x.ownerId===null&&x.routeTarget===routeTarget&&x.loginContinuation);if(guest){saved={...guest,ownerId,loginContinuation:false};const interest=session.ui?.serviceInformationInterest;patch({ui:{...session.ui,supportDrafts:list.filter(x=>x!==guest).concat(saved),...(interest?.ownerId===null&&routeTarget===''?{serviceInformationInterest:{...interest,ownerId}}:{})}});}}if(saved&&ownerId&&routeTarget===''){const guest=list.find(x=>x.ownerId===null&&x.routeTarget===''&&x.loginContinuation),interest=session.ui?.serviceInformationInterest;if(guest&&interest?.ownerId===null&&serviceInformationItem(interest.serviceId)){patch({ui:{...session.ui,supportDrafts:list.map(x=>x===guest?{...x,loginContinuation:false}:x),serviceInformationInterest:{...interest,ownerId,phrase:guest.message}}});}}return saved||{ownerId,routeTarget,topic:'support',target:routeTarget||'general',message:''};}
function saveSupportDraft(value){const list=Array.isArray(session.ui?.supportDrafts)?session.ui.supportDrafts:[];patch({ui:{...session.ui,supportDrafts:list.filter(x=>!(x.ownerId===value.ownerId&&x.routeTarget===value.routeTarget)).concat(value)}});return value;}
