function supportTargets(){const targets=[['general',st('general')],...owned('bookings').map(x=>['booking:'+x.id,itemTitle(x)+' · '+date(x.date)]),...owned('visits').map(x=>['visit:'+x.id,t('visits')+' · '+date(x.date||x.createdAt)+' · '+t(x.status)])];for(const [list,type,key]of [['orders','order','orders'],['entitlements','entitlement','entitlement'],['memberships','membership','membership'],['giftCards','giftCard','giftCard'],['events','event','events'],['retail','retail','products'],['facilityAccess','facilityAccess','facilityEntries'],['programConsultations','programConsultation','programConsultation'],['programPlans','programPlan','programPlan'],['cafeOrders','cafeOrder','cafeOrders'],['requests','request','requests']])for(const x of owned(list)){const title=type==='request'?t(x.type==='cancel'?'cancelRequest':x.type==='reschedule'?'change':x.type==='support'?'support':'request'):name(x)||t(key);targets.push([type+':'+x.id,t(key)+' · '+title+(x.date?' · '+date(x.date):x.createdAt?' · '+date(x.createdAt):'')+(x.status?' · '+t(x.status):'')]);}return targets;}
