function requestRecordTitle(record){const titles={support:['Destek talebi','Dəstək sorğusu','Обращение в поддержку'],cancel:['İptal talebi','Ləğv sorğusu','Запрос на отмену'],reschedule:['Değişiklik talebi','Dəyişiklik sorğusu','Запрос на изменение'],change:['Değişiklik talebi','Dəyişiklik sorğusu','Запрос на изменение'],refund:['İade inceleme talebi','Qaytarılmanın yoxlanılması sorğusu','Запрос на проверку возврата'],'order-refund':['Sipariş iadesi incelemesi','Sifariş qaytarılmasının yoxlanılması','Проверка возврата заказа'],'retail-refund':['Ürün iadesi incelemesi','Məhsul qaytarılmasının yoxlanılması','Проверка возврата товара'],'membership-freeze':['Üyelik dondurma talebi','Üzvlüyün dondurulması sorğusu','Запрос на заморозку абонемента'],'membership-resume':['Üyeliği sürdürme talebi','Üzvlüyün davamı sorğusu','Запрос на возобновление абонемента'],'membership-renew':['Üyelik yenileme talebi','Üzvlüyün yenilənməsi sorğusu','Запрос на продление абонемента'],'cafe-reward':['İkram talebi','İkram sorğusu','Запрос на угощение'],prerequisite:['Uygunluk değerlendirme talebi','Uyğunluğun qiymətləndirilməsi sorğusu','Запрос на проверку допуска'],package:['Paket bilgi talebi','Paket məlumatı sorğusu','Запрос о пакете']},fallback=['Talep kaydı','Sorğu qeydi','Запись обращения'];return (titles[record?.type]||fallback)[{tr:0,az:1,ru:2}[language]??0];}
