function connection(){const p=session.pending;if(!p||(p.customerId&&p.customerId!==cid()))return header('checkOperation','home')+sourceEmpty('operation')+link('home','home');const retryTitle=entryCopy('Yeniden Deneyebilirsiniz','Yenidən Cəhd Edə Bilərsiniz','Можно повторить'),retryHelp=entryCopy('İşlem durumu sorgulandı. Aynı işlem kimliği ve seçimlerle yeniden deneyebilirsiniz.','Əməliyyatın statusu sorğu edildi. Eyni əməliyyat nömrəsi və seçimlərlə yenidən cəhd edə bilərsiniz.','Статус операции проверен. Можно повторить с тем же номером операции и выбранными параметрами.'),brief=p.command==='book'&&!p.knownResult,queryLabel=brief?entryCopy('Durumu Kontrol Et','Statusu Yoxla','Проверить статус'):entryCopy('Durumu Sorgula','Statusu Sorğu Et','Запросить статус'),query=`<button type="button" class="btn" data-action="check-operation" ${busy?'disabled':''}>${e(queryLabel)}</button>`,retry=`<button type="button" class="btn secondary" ${p.retryAllowed?'data-action="retry-operation"':''} ${busy||!p.retryAllowed?'disabled':''}>${e(entryCopy('Tekrar Dene','Yenidən Cəhd Et','Повторить'))}</button>`,count=(session.pendingCount||0)>1?`<p class="source-connection-count">${e(t('pendingCount',{count:session.pendingCount}))}</p>`:'';
if(brief)return `<section class="source-connection-screen" data-source="connection_failure"><div class="source-connection-symbol">${sourceIcon('solar:cloud-cross-bold-duotone','discover')}<span>${sourceIcon('solar:refresh-linear','clock')}</span></div><h1 tabindex="-1">${e(p.retryAllowed?retryTitle:entryCopy('Bağlantı Bekleniyor','Bağlantı Gözlənilir','Ожидаем соединения'))}</h1><p>${e(p.retryAllowed?retryHelp:entryCopy('İşlem sonucu şu an bilinmiyor. Tekrar göndermeden önce randevu durumunuzu kontrol edin.','Əməliyyatın nəticəsi hələ məlum deyil. Yenidən göndərməzdən əvvəl rezervasiyanın statusunu yoxlayın.','Результат операции пока неизвестен. Перед повторной отправкой проверьте статус записи.'))}</p>${count}<div class="source-connection-actions">${query}${retry}</div><a class="source-connection-close" href="#home">${e(entryCopy('Şimdilik Kapat','Hələlik Bağla','Пока закрыть'))}</a></section>`;
return `<section class="source-recovery-screen" data-source="operation_recovery"><header class="source-recovery-header"><a class="icon-button" href="#home" aria-label="${e(t('close'))}">${sourceIcon('lucide:x','close')}</a></header><div class="source-recovery-body"><div class="source-recovery-symbol"><span></span>${sourceIcon('solar:globus-linear','discover')}</div><h1 tabindex="-1">${e(p.knownResult?t('knownCommit'):p.retryAllowed?retryTitle:entryCopy('Bağlantı Kesildi','Bağlantı Kəsildi','Соединение прервано'))}</h1><p>${e(p.knownResult?t('unknownHelp'):p.retryAllowed?retryHelp:entryCopy('İşlem sonucu henüz bilinmiyor. Tekrar denemeden önce son durumu sorgulayın. Seçimleriniz ve işlem kaydınız korunuyor.','Əməliyyatın nəticəsi hələ məlum deyil. Yenidən cəhd etməzdən əvvəl son statusu sorğu edin. Seçiminiz və əməliyyat qeydi saxlanılır.','Результат операции пока неизвестен. Перед повторной отправкой проверьте статус. Ваш выбор и запись операции сохранены.'))}</p>${count}<div class="source-recovery-operation"><span>${e(entryCopy('İşlem Numarası','Əməliyyat Nömrəsi','Номер операции'))}</span><code>${e(p.operationId||p.id||'—')}</code></div><button type="button" class="source-recovery-export" data-action="export-operation-report">${sourceIcon('solar:upload-minimalistic-linear','right')}${e(entryCopy('Hata Raporunu Kaydet','Xəta Hesabatını Saxla','Сохранить отчёт об ошибке'))}</button><div class="source-recovery-actions">${query}${p.retryAllowed?retry:''}<button type="button" class="source-recovery-reset" disabled aria-describedby="source-recovery-reset-reason">${e(entryCopy('Uygulamayı Sıfırla','Tətbiqi Sıfırla','Сбросить приложение'))}</button></div></div>${footer(`<aside class="source-recovery-warning" id="source-recovery-reset-reason">${sourceIcon('solar:shield-warning-bold','info')}<p><strong>${e(entryCopy('Önemli:','Vacib:','Важно:'))}</strong> ${e(entryCopy('Sonuç belirsizken veriler sıfırlanamaz. Önce durumu sorgulayın; işlem kaydınız korunur.','Nəticə qeyri-müəyyən olduqda məlumatlar sıfırlana bilməz. Əvvəl statusu sorğu edin; əməliyyat qeydi saxlanılır.','Пока результат неизвестен, данные нельзя сбросить. Сначала проверьте статус; запись операции сохранена.'))}</p></aside>`)}</section>`;}

function recovery(){return `<header><h1 tabindex="-1">${e(t('recovery'))}</h1></header>${note('error','error')}${button('export','export-recovery','','secondary')}${form('reset',`<label class="choice"><input type="checkbox" name="explicit" required>${e(t('resetConfirm'))}</label>${submit('reset')}`)}`;}
